  Gain_out1 <= to_signed(16#5000#, 16) * Delay2_out1;

  Gain_out1_1 <= (resize(Gain_out1(31 DOWNTO 20), 16)) + ('0' & (Gain_out1(19) AND (( NOT Gain_out1(31)) OR (Gain_out1(18) OR Gain_out1(17) OR Gain_out1(16) OR Gain_out1(15) OR Gain_out1(14) OR Gain_out1(13) OR Gain_out1(12) OR Gain_out1(11) OR Gain_out1(10) OR Gain_out1(9) OR Gain_out1(8) OR Gain_out1(7) OR Gain_out1(6) OR Gain_out1(5) OR Gain_out1(4) OR Gain_out1(3) OR Gain_out1(2) OR Gain_out1(1) OR Gain_out1(0)))));

  Delay3_process : PROCESS (clk)
  BEGIN
    IF clk'EVENT AND clk = '1' THEN
      IF reset = '1' THEN
        Delay3_reg <= (OTHERS => to_signed(16#0000#, 16));
      ELSIF enb_1_8_0 = '1' THEN
        Delay3_reg(0) <= Gain_out1_1;
        Delay3_reg(1) <= Delay3_reg(0);
      END IF;
    END IF;
  END PROCESS Delay3_process;

  Delay3_out1 <= Delay3_reg(1);

  Constant_out1 <= to_signed(16#00C9#, 16);

  Add_out1 <= Delay3_out1 + Constant_out1;

  Delay1_process : PROCESS (clk)
  BEGIN
    IF clk'EVENT AND clk = '1' THEN
      IF enb_1_8_0 = '1' THEN
        Delay1_reg(0) <= Add_out1;
        Delay1_reg(1) <= Delay1_reg(0);
      END IF;
    END IF;
  END PROCESS Delay1_process;

  Delay1_out1 <= Delay1_reg(1);

  
  prelookup_idx <= to_unsigned(16#000#, 9) WHEN Delay1_out1 <= to_signed(16#0000#, 16) ELSE
      to_unsigned(16#1FF#, 9) WHEN Delay1_out1 >= to_signed(16#01FF#, 16) ELSE
      unsigned(Delay1_out1(8 DOWNTO 0));

  sqrt_noisePow_2_out1 <= sqrt_noisePow_2_data(to_integer(prelookup_idx));

  Delay4_process : PROCESS (clk)
  BEGIN
    IF clk'EVENT AND clk = '1' THEN
      IF enb_1_8_0 = '1' THEN
        Delay4_reg(0) <= sqrt_noisePow_2_out1;
        Delay4_reg(1) <= Delay4_reg(0);
      END IF;
    END IF;
  END PROCESS Delay4_process;

  Delay4_out1 <= Delay4_reg(1);

  Delay6_process : PROCESS (clk)
  BEGIN
    IF clk'EVENT AND clk = '1' THEN
      IF enb_1_8_0 = '1' THEN
        Delay6_out1 <= Delay4_out1;
      END IF;
    END IF;
  END PROCESS Delay6_process;


  noiseVar <= std_logic_vector(Delay6_out1);

END rtl;

